SELECT

FROM activity_enrollment



        AND activity_enrollment.activity_id = #{queryForm.activityId}



        AND activity_enrollment.user_id = #{queryForm.userId}



        AND activity_enrollment.deleted_flag = #{queryForm.deletedFlag}



        AND activity_enrollment.sign_in_status = #{queryForm.signInStatus}

SELECT activity_enrollment.activity_id, activity_enrollment.sign_in_status, activity_enrollment.sign_out_status, activity_enrollment.create_time AS enroll_time, activity.title AS activity_title, activity.cover_img, activity.position, activity.status AS activity_status, activity.paid_flag, activity.price_fen, activity.score_can_get, activity.need_sign_out, activity_schedule.enroll_end_time, activity_schedule.activity_start_time, activity_schedule.activity_end_time FROM activity_enrollment LEFT JOIN activity ON activity.id = activity_enrollment.activity_id LEFT JOIN activity_schedule ON activity_schedule.activity_id = activity_enrollment.activity_id WHERE activity_enrollment.user_id = #{userId} AND activity_enrollment.deleted_flag = 0
AND activity_enrollment.sign_in_status = #{queryForm.signInStatus}
ORDER BY activity_enrollment.create_time DESC

